/**
 * Summary of the synthetic validation of the engine's error (specification 08), as
 * generated by `pnpm --filter @app/validation quality:fit` from the measured rows of
 * `quality:run`. Simulated data: every number in it comes from fictional exams drawn
 * by the virtual instrument. The full report is `packages/validation/out/quality-validation.md`.
 *
 * Nothing here is written by hand: the "How it works" screen shows these numbers as
 * they come, and a test checks that the file is what the command produces.
 */
import type { SimulatedErrorModelSpec } from '../rules/simulatedErrorModel';
import { simulatedErrorModel } from '../rules/simulatedErrorModel';
import summary from './validation-summary.json';

export const VALIDATION_SUMMARY_FORMAT = 'validation-summary-1';

export type ValidationPartition = 'development' | 'test-anatomy' | 'test-family';
export type ValidationMeasure = 'trt' | 'roughness';

/** Error of the change of one measure on the pairs of one partition that the engine and the model accepted. µm unless stated. */
export interface MeasureResult {
  pairs: number;
  eyes: number;
  biasUm: number;
  rmseUm: number;
  maeUm: number;
  maxAbsUm: number;
  /** Median standard error the model gives these pairs. */
  medianSeUm: number;
  /** Fraction of pairs whose true change is inside ±1.96 σ, with its Wilson 95 % interval. */
  coverage: number;
  coverageLow: number;
  coverageHigh: number;
  /** Fraction of pairs with |error| > 3 σ (a normal gives 0.27 %). */
  beyond3Se: number;
}

export interface PartitionSummary {
  crew: string[];
  eyes: number;
  captures: number;
  /** Captures the engine refused (geometric or signal reasons). */
  engineRefused: number;
  /** Captures the engine accepted but the error model does not support. */
  modelRefused: number;
  /** Follow-up captures compared with a reference, both accepted by engine and model. */
  pairs: number;
  results: Record<ValidationMeasure, MeasureResult>;
}

export interface CriterionResult {
  id: string;
  partition: ValidationPartition;
  measure: ValidationMeasure | 'both';
  value: number;
  limit: number;
  comparison: '<=' | '>=';
  passed: boolean;
}

export interface ValidationSummary {
  format: typeof VALIDATION_SUMMARY_FORMAT;
  simulated: true;
  notice: string;
  protocol: string;
  versions: { engine: string; instrument: string; examFormat: string; scanFormat: string; model: string };
  sample: { crewMembers: number; eyes: number; references: number; captures: number };
  partitions: Record<ValidationPartition, PartitionSummary>;
  /** Correlation between the error of today's exam and that of its reference (TRT, accepted pairs of every partition). */
  examErrorCorrelation: { trt: number; roughness: number; pairs: number; references: number };
  /** Accepted pairs with an error beyond the engineering tolerance: the examples a quality classifier would need. */
  grossErrors: { trt: number; roughness: number; toleranceTrtUm: number; toleranceRoughnessUm: number };
  model: SimulatedErrorModelSpec;
  decision: { activate: boolean; criteria: CriterionResult[] };
}

export const VALIDATION_SUMMARY = summary as unknown as ValidationSummary;

/** The error model fitted in the validation, whether or not it is the active one. */
export const SIMULATED_ERROR_MODEL = simulatedErrorModel(VALIDATION_SUMMARY.model);
